style.css:
@-moz-document url-prefix("https://www.roblox.com/") {
html, body {
        background: url("https://i.imgur.com/EsFq3Mx.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: transparent !important;
    }

    /* Elimină fundalurile albe de pe containere principale */
    body * {
        background-color: transparent !important;
    }

    /* Setează textul să rămână lizibil pe fundal închis */
    body, body * {
        color: #ffffff !important;
    }
}
